const startups = $input.all().map(item => item.json);
const cleaned = startups.filter(s => !((s.name || '').toLowerCase().includes('test')));
return cleaned.map(s => ({ json: s }));

const customers = $input.all().map(item => item.json);
const cleaned = customers.filter(c => !((c.companyName || c.name || '').toLowerCase().includes('test')));
return cleaned.map(c => ({ json: c }));

const cases = $('Fetch Use Case Views').all().map(item => item.json);
const cleanStartupIds = new Set($('Remove Test Startups').all().map(item => item.json.id));

const cleaned = cases.filter(c => c.startup && cleanStartupIds.has(c.startup.id));

return cleaned.map(c => ({ json: c }));

const startups = $input.all().map(item => item.json);

const monthlyCounts = {};
for (const s of startups) {
  if (!s.createdAt) continue;
  const d = new Date(s.createdAt);
  if (isNaN(d.getTime())) continue;
  const key = d.toISOString().slice(0, 7);
  monthlyCounts[key] = (monthlyCounts[key] || 0) + 1;
}

const months = Object.keys(monthlyCounts).sort();
const newCounts = months.map(m => monthlyCounts[m]);
const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const labels = months.map(m => {
  const [y, mo] = m.split('-');
  return monthNames[Number(mo) - 1] + ' ' + y.slice(2);
});

let running = 0;
const cumulative = newCounts.map(c => { running += c; return running; });

let linkedUseCases = 0;
let startupsWithZero = 0;
for (const s of startups) {
  const n = Array.isArray(s.cases) ? s.cases.length : 0;
  linkedUseCases += n;
  if (n === 0) startupsWithZero++;
}
const avgPerStartup = startups.length ? Number((linkedUseCases / startups.length).toFixed(2)) : 0;

const chartConfig = {
  chart: {
    type: 'bar',
    data: {
      labels,
      datasets: [
        {
          type: 'bar',
          label: 'New',
          data: newCounts,
          backgroundColor: '#7C6FEC',
          yAxisID: 'y-new'
        },
        {
          type: 'line',
          label: 'Cumulative',
          data: cumulative,
          borderColor: '#1baf7a',
          backgroundColor: 'rgba(27,175,122,0.08)',
          fill: true,
          lineTension: 0.3,
          pointRadius: 4,
          pointBackgroundColor: '#1baf7a',
          borderWidth: 2,
          yAxisID: 'y-cumul'
        }
      ]
    },
    options: {
      title: { display: true, text: 'Monthly registrations' },
      legend: { display: true },
      scales: {
        yAxes: [
          {
            id: 'y-new',
            type: 'linear',
            position: 'left',
            ticks: { beginAtZero: true },
            scaleLabel: { display: true, labelString: 'New' }
          },
          {
            id: 'y-cumul',
            type: 'linear',
            position: 'right',
            ticks: { beginAtZero: true },
            gridLines: { drawOnChartArea: false },
            scaleLabel: { display: true, labelString: 'Total' }
          }
        ]
      }
    }
  },
  width: 760,
  height: 380,
  backgroundColor: 'white',
  format: 'png'
};

return [{
  json: {
    stats: {
      totalStartups: startups.length,
      linkedUseCases,
      avgUseCasesPerStartup: avgPerStartup,
      startupsWithZeroUseCases: startupsWithZero,
      monthlyGrowth: months.map((m, i) => ({ month: labels[i], count: newCounts[i] }))
    },
    chartConfig
  }
}];

const startups = $input.all().map(item => item.json);

const countryCounts = {};
for (const s of startups) {
  const country = (s.location || 'Unknown').trim() || 'Unknown';
  countryCounts[country] = (countryCounts[country] || 0) + 1;
}

const sorted = Object.entries(countryCounts).sort((a, b) => b[1] - a[1]).slice(0, 10);
const labels = sorted.map(([country]) => country);
const counts = sorted.map(([, count]) => count);

const chartConfig = {
  chart: {
    type: 'bar',
    data: { labels, datasets: [{ label: 'Startups', data: counts, backgroundColor: '#4C6EF5' }] },
    options: { indexAxis: 'y', plugins: { title: { display: true, text: 'Top locations' }, legend: { display: false } } }
  },
  width: 760,
  height: 420,
  backgroundColor: 'white',
  format: 'png'
};

return [{
  json: { stats: { topCountries: sorted.map(([country, count]) => ({ country, count })) }, chartConfig }
}];

const customers = $input.all().map(item => item.json);

const monthlyCounts = {};
for (const c of customers) {
  if (c.createdAt) {
    const d = new Date(c.createdAt);
    if (!isNaN(d.getTime())) {
      const key = d.toISOString().slice(0, 7);
      monthlyCounts[key] = (monthlyCounts[key] || 0) + 1;
    }
  }
}

const subscribed = customers.filter(c => c.isSubscribed).length;
const notSubscribed = customers.length - subscribed;

const months = Object.keys(monthlyCounts).sort();
const newCounts = months.map(m => monthlyCounts[m]);
const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const labels = months.map(m => {
  const [y, mo] = m.split('-');
  return monthNames[Number(mo) - 1] + ' ' + y.slice(2);
});

let running = 0;
const cumulative = newCounts.map(c => { running += c; return running; });

const chartConfig = {
  chart: {
    type: 'bar',
    data: {
      labels,
      datasets: [
        {
          type: 'bar',
          label: 'New',
          data: newCounts,
          backgroundColor: '#F76707',
          yAxisID: 'y-new'
        },
        {
          type: 'line',
          label: 'Cumulative',
          data: cumulative,
          borderColor: '#1baf7a',
          backgroundColor: 'rgba(27,175,122,0.08)',
          fill: true,
          lineTension: 0.3,
          pointRadius: 4,
          pointBackgroundColor: '#1baf7a',
          borderWidth: 2,
          yAxisID: 'y-cumul'
        }
      ]
    },
    options: {
      title: { display: true, text: 'Customer Monthly Growth' },
      legend: { display: true },
      scales: {
        yAxes: [
          {
            id: 'y-new',
            type: 'linear',
            position: 'left',
            ticks: { beginAtZero: true },
            scaleLabel: { display: true, labelString: 'New' }
          },
          {
            id: 'y-cumul',
            type: 'linear',
            position: 'right',
            ticks: { beginAtZero: true },
            gridLines: { drawOnChartArea: false },
            scaleLabel: { display: true, labelString: 'Total' }
          }
        ]
      }
    }
  },
  width: 700,
  height: 380,
  backgroundColor: 'white',
  format: 'png'
};

return [{
  json: {
    stats: {
      totalCustomers: customers.length,
      subscribed,
      notSubscribed,
      monthlyGrowth: months.map((m, i) => ({ month: labels[i], count: newCounts[i] }))
    },
    chartConfig
  }
}];

const cases = $input.all().map(item => item.json);

const byStatus = {};
for (const c of cases) {
  const raw = (c.status || 'Unknown').trim();
  const status = raw.charAt(0).toUpperCase() + raw.slice(1).toLowerCase();
  byStatus[status] = (byStatus[status] || 0) + 1;
}

const topByViews = cases.slice().sort((a, b) => (b.totalViews || 0) - (a.totalViews || 0)).slice(0, 10);
const labels = topByViews.map(c => (c.title && c.title.length > 30) ? c.title.slice(0, 27) + '...' : (c.title || 'Untitled'));
const counts = topByViews.map(c => c.totalViews || 0);

const chartConfig = {
  chart: {
    type: 'bar',
    data: { labels, datasets: [{ label: 'Views', data: counts, backgroundColor: '#AE3EC9' }] },
    options: { indexAxis: 'y', plugins: { title: { display: true, text: 'Top 10 Use Cases by Views' }, legend: { display: false } } }
  },
  width: 700,
  height: 420,
  backgroundColor: 'white',
  format: 'png'
};

return [{
  json: { stats: { totalUseCases: cases.length, byStatus, topByViews: topByViews.map(c => ({ title: c.title, views: c.totalViews || 0 })) }, chartConfig }
}];

const startups = $input.all().map(item => item.json);

const withCounts = startups.map(s => {
  const cases = Array.isArray(s.cases) ? s.cases : [];
  const approvedCount = cases.filter(c => (c.status || '').trim().toLowerCase() === 'approved').length;
  return { name: s.name || 'Unknown', count: approvedCount };
});

const sorted = withCounts.slice().sort((a, b) => b.count - a.count).slice(0, 10);

const labels = sorted.map(s => s.name);
const counts = sorted.map(s => s.count);

const chartConfig = {
  chart: {
    type: 'bar',
    data: { labels, datasets: [{ label: 'Approved Use Cases', data: counts, backgroundColor: '#12B886' }] },
    options: { indexAxis: 'y', plugins: { title: { display: true, text: 'Top 10 startups by approved use cases linked' }, legend: { display: false } } }
  },
  width: 760,
  height: 420,
  backgroundColor: 'white',
  format: 'png'
};

return [{
  json: { stats: { topStartupsByUseCases: sorted }, chartConfig }
}];

